function validate([p, q, root]) {
  const values = root.filter(v => v !== null);
  if (values.length < 2) return 'The tree needs at least two nodes.';
  if (values.length > 100000) return 'The tree has at most 10^5 nodes.';
  if (values.some(v => v < -1000000000 || v > 1000000000)) return 'Node values are between -10^9 and 10^9.';
  if (new Set(values).size !== values.length) return 'Node values must be unique.';
  if (!Number.isInteger(p) || !Number.isInteger(q)) return 'p and q are given as node values.';
  if (p === q) return 'p and q must be different nodes.';
  if (!values.includes(p) || !values.includes(q)) return 'p and q must both be values in the tree.';
  return null;
}

