function adapt(input, solve, kit) {
  const [p, q, root] = input;
  class Node {
    constructor(val) { this.val = val; this.left = null; this.right = null; this.parent = null; }
  }
  // Build the tree level by level, linking every child back to its parent.
  const nodes = [new Node(root[0])];
  let next = 1;
  for (let head = 0; head < nodes.length && next < root.length; head++) {
    for (const side of ['left', 'right']) {
      if (next < root.length && root[next] !== null) {
        const child = new Node(root[next]);
        child.parent = nodes[head];
        nodes[head][side] = child;
        nodes.push(child);
      }
      next++;
    }
  }
  const links = nodes.map(node => [node.val, node.left, node.right, node.parent]);
  const result = solve(nodes.find(node => node.val === p), nodes.find(node => node.val === q));
  const intact = nodes.every((node, i) => node.val === links[i][0] && node.left === links[i][1] && node.right === links[i][2] && node.parent === links[i][3]);
  if (!intact) throw new Error('The tree must not be modified.');
  if (result === undefined) throw new Error('The solution did not return a value.');
  if (result === null) return null;
  if (!nodes.includes(result)) throw new Error('Return a node of the tree.');
  return result.val;
}

