function lowestCommonAncestor(p, q) {
  let fromP = p;
  let fromQ = q;
  while (fromP !== fromQ) {
    fromP = fromP === null ? q : fromP.parent;
    fromQ = fromQ === null ? p : fromQ.parent;
  }
  return fromP;
}

