function lowestCommonAncestor(p, q) {
  // Remember every ancestor of p (p included), then climb from q until one is found.
  const ancestors = new Set();
  for (let node = p; node; node = node.parent) ancestors.add(node);
  let node = q;
  while (!ancestors.has(node)) node = node.parent;
  return node;
}

